// Shared reachability computation: which channels this subscriber can actually be reached on, in precedence
// order. Used by both the router and the audit, so the two cannot disagree.

export function reachableChannelsFor(subscriber) {
	const reachable = [];
	if (subscriber.phone && subscriber.verified === true) reachable.push("sms");
	if (subscriber.pushToken) reachable.push("push");
	if (subscriber.webhookUrl) reachable.push("webhook");
	if (subscriber.email) reachable.push("email");
	return reachable;
}

export function reachableSummaryFor(reachable) {
	return reachable.join("|") || "none";
}

// Shared input validation for events and subscribers.

export function validateEvent(event) {
	if (!event || typeof event.kind !== "string") {
		throw new TypeError("an event needs a kind");
	}
}

export function validateSubscriber(subscriber) {
	if (!subscriber || typeof subscriber.id !== "string") {
		throw new TypeError("a subscriber needs an id");
	}
}

// Per-kind routing rules: precedence order and reason text. Adding a kind or a channel is adding data here,
// not another branch in a shared function.

const RULES = {
	security_alert: {
		precedence: [
			{ channel: "sms", reason: "security alerts go to a verified phone first" },
			{ channel: "email", reason: "security alerts fall back to email" },
		],
		noneReason: "no reachable channel for a security alert",
	},
	billing: {
		precedence: [{ channel: "email", reason: "billing always goes to email" }],
		noneReason: "billing needs an email address",
	},
	mention: {
		quietReason: "mentions are suppressed during quiet hours",
		precedence: [
			{ channel: "push", reason: "mentions go to push when available" },
			{ channel: "email", reason: "mentions fall back to email" },
		],
		noneReason: "no reachable channel for a mention",
	},
	digest: {
		quietReason: "digests are suppressed during quiet hours",
		precedence: [
			{ channel: "webhook", reason: "digests prefer a webhook" },
			{ channel: "email", reason: "digests fall back to email" },
		],
		noneReason: "no reachable channel for a digest",
	},
};

export function decideChannel(kind, quiet, reachable) {
	const rule = RULES[kind];
	if (!rule) {
		return { channel: null, reason: `unknown event kind ${kind}` };
	}
	if (quiet && rule.quietReason) {
		return { channel: null, reason: rule.quietReason };
	}
	for (const option of rule.precedence) {
		if (reachable.includes(option.channel)) {
			return { channel: option.channel, reason: option.reason };
		}
	}
	return { channel: null, reason: rule.noneReason };
}

// Notification routing. Adding a kind or a channel is adding data to routingRules.mjs, not another branch here.

import { reachableChannelsFor, reachableSummaryFor } from "./reachability.mjs";
import { validateEvent, validateSubscriber } from "./validation.mjs";
import { decideChannel } from "./routingRules.mjs";

export const CHANNELS = ["email", "sms", "push", "webhook"];

export function routeNotification(event, subscriber) {
	validateEvent(event);
	validateSubscriber(subscriber);
	const reachable = reachableChannelsFor(subscriber);
	const reachableSummary = reachableSummaryFor(reachable);
	const decision = decideChannel(event.kind, subscriber.quietHours === true, reachable);
	return { channel: decision.channel, reason: decision.reason, subscriberId: subscriber.id, reachableSummary };
}

export function routeAll(event, subscribers) {
	return (subscribers ?? []).map((subscriber) => routeNotification(event, subscriber));
}

// Routability audit. Shares the reachability computation and validation with the router, so the two cannot
// drift apart.

import { reachableChannelsFor, reachableSummaryFor } from "./reachability.mjs";
import { validateSubscriber } from "./validation.mjs";

export function auditRoutability(subscriber) {
	validateSubscriber(subscriber);
	const reachable = reachableChannelsFor(subscriber);
	const reachableSummary = reachableSummaryFor(reachable);
	return { subscriberId: subscriber.id, reachableSummary, reachableCount: reachable.length };
}
